380      public static int intToIntPower(int a, int b) {
381  	if (b <= 0) {
382  	    if (b == 0 || a == 1) return 1;
383  	    else if (a < 0) throw Utility.makeFortressException("fortress.CompilerBuiltin$DivisionByZero");
384  	    else return 0;
385  	}
386  	long result = 1;
387  	long x = a;
388  	do {
389  	    if (x != (int) x) throw Utility.makeFortressException("fortress.CompilerBuiltin$IntegerOverflow");
390  	    if ((b & 1) != 0) {
391  		result *= x;
392  		if (result != (int) result) throw Utility.makeFortressException("fortress.CompilerBuiltin$IntegerOverflow");
393  	    }
394  	    b >>= 1;
395  	    x *= x;
396  	} while (b > 0);
397  	return (int) result;
398      }

